PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE src_trainers (
  id     INTEGER NOT NULL,           -- 生物編號
  who    TEXT    NOT NULL,           -- 回報的人的代號（站長自己記的是 owner）
  ttype  INTEGER NOT NULL,           -- C_Trainer.GetTrainerType()：0 一般（職業訓練師）、2 專業技能、3 寵物
  cls    INTEGER NOT NULL,           -- 打開視窗的角色是什麼職業（職業訓練師只教自己的職業）
  skills TEXT    NOT NULL,           -- 教的技能屬於哪些技能線（遊戲裡的名稱，例如「烹飪」；+ 連起來，最多 3 個）
  at     INTEGER NOT NULL,           -- 最近一次記到的時間（伺服器時間）
  PRIMARY KEY (id, who)
);
